import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider nonnegative integer-valued functions f and g defined on all nonnegative integers. Fix parameters {m}, {r_parts}, {budget}, {delta}, and {quantum}. The function f must satisfy: (i) f(0) >= f(1) >= ... >= f({m}) >= 0; (ii) the discrete Lipschitz condition f(i) - f(i+1) <= {delta} for all 0 <= i < {m}; (iii) the quantization constraint that each f(i) is a multiple of {quantum}; and (iv) the budget constraint f(0) + f(1) + ... + f({m}) <= {budget}. For every integer t with 0 <= t <= {m}, write t = {r_parts}*q + a with q = floor(t/{r_parts}) and 0 <= a < {r_parts}. Then the pair (f, g) must satisfy the aggregator bound g(t) <= ({r_parts} - a) * f(q) + a * f(q+1). Define a weight function w(t) = max(0, {w0} - {w_decay}*t). Determine the maximum possible value of the weighted total W = sum_{t=0}^{m} w(t) * g(t) over all such pairs (f, g).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose parameters
m = rng.randint(180, 420)
r_parts = rng.randint(5, max(6, min(30, m // 3)))
delta = rng.randint(1, min(7, r_parts))
quantum = rng.randint(1, 3)
# choose weight function
use_linear = rng.random() < 0.5
if use_linear:
    w_decay = 1
    w0 = rng.randint(max(3, m // 8), max(6, m // 6))
else:
    w_decay = 0
    w0 = rng.randint(2, 7)
# build coefficient vector C to ensure monotonicity
def build_C(m, r_parts, w0, w_decay):
    C = [0] * (m + 1)
    for t in range(m + 1):
        w = max(0, w0 - w_decay * t)
        q = t // r_parts
        a = t - r_parts * q
        if q <= m:
            C[q] += w * (r_parts - a)
            if q + 1 <= m:
                C[q + 1] += w * a
    return C
C = build_C(m, r_parts, w0, w_decay)
tries = 0
while any(C[i] < C[i + 1] for i in range(m)):
    # enforce monotone coefficients by switching to constant weights
    w_decay = 0
    w0 = rng.randint(2, 7)
    C = build_C(m, r_parts, w0, w_decay)
    tries += 1
    if tries > 5:
        break
# choose a target H to shape the budget to a nontrivial range
J_target = rng.randint(max(2, m // 12), max(3, m // 8))
H_target = J_target * delta + rng.randint(1, delta)
# quantize H
H_target = max(quantum, (H_target // quantum) * quantum)
J = min(m, H_target // delta)
sum_b = (J + 1) * H_target - delta * (J * (J + 1) // 2)
fudge = 0
if sum_b > 20:
    fudge = rng.randint(-(sum_b // 10), (sum_b // 10))
budget = max(quantum, sum_b + fudge)
return {
    'm': m,
    'r_parts': r_parts,
    'budget': budget,
    'delta': delta,
    'quantum': quantum,
    'w0': w0,
    'w_decay': w_decay
}

    def verifier(assign):
# validate basic structure
try:
    m = int(assign['m'])
    r = int(assign['r_parts'])
    B = int(assign['budget'])
    d = int(assign['delta'])
    qnt = int(assign['quantum'])
    w0 = int(assign['w0'])
    wd = int(assign['w_decay'])
except Exception:
    return (False, None)  # invalid types
if m < 2 or r < 2 or B < 1 or d < 1 or qnt < 1 or w0 < 1 or wd < 0:
    return (False, None)
# build coefficient vector C_j for the linear objective in f(j)
C = [0] * (m + 1)
for t in range(m + 1):
    w = w0 - wd * t
    if w < 0:
        w = 0
    q = t // r
    a = t - r * q
    if q <= m:
        C[q] += w * (r - a)
        if q + 1 <= m:
            C[q + 1] += w * a
# enforce the difficulty-ensuring monotonicity of coefficients
if any(C[i] < C[i + 1] for i in range(m)):
    # Coefficients should be nonincreasing to ensure the greedy/water-filling optimal structure
    return (False, None)
# We now solve: maximize sum_j C[j]*f(j) subject to
#   f nonincreasing, f(j)-f(j+1) <= d, f(j) in multiples of qnt, sum f(j) <= B
# Under C nonincreasing, the optimal f is of the steepest allowed form: f(j) = max(0, H - d*j)
# for some H multiple of qnt, truncated at zero, and respecting the budget.
# We search over admissible H.
best = 0
# Upper bound for H: cannot exceed both budget and the maximum spread d*m plus one quantum step
H_upper = min(B, d * m + qnt)
if H_upper < qnt:
    return (False, None)
for H in range(qnt, H_upper + 1, qnt):
    J = min(m, H // d)  # last index with positive f(j)
    # compute sum of f(j): sum_{j=0}^{J} (H - d*j)
    Sf = (J + 1) * H - d * (J * (J + 1) // 2)
    if Sf > B:
        continue
    # objective
    S = 0
    # only j up to J contribute; beyond J f=0
    for j in range(J + 1):
        fval = H - d * j
        # fval automatically multiple of qnt if H is multiple of qnt and d is integer; no need to round
        S += C[j] * fval
    if S > best:
        best = S
answer = best
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

